-- Simple in-app e-signature (FR-DOC-014; ADR 022).
-- Part 1: generated by prisma migrate diff.

-- CreateTable
CREATE TABLE "signature_requests" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "org_id" UUID NOT NULL,
    "document_id" UUID NOT NULL,
    "source_version_id" UUID NOT NULL,
    "source_sha256" CHAR(64) NOT NULL,
    "requested_by" UUID NOT NULL,
    "message" TEXT NOT NULL DEFAULT '',
    "status" VARCHAR(10) NOT NULL DEFAULT 'OPEN',
    "signed_version_id" UUID,
    "signed_sha256" CHAR(64),
    "key_wrapped" BYTEA NOT NULL,
    "key_id" VARCHAR(100) NOT NULL,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "completed_at" TIMESTAMPTZ,

    CONSTRAINT "signature_requests_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "signature_signers" (
    "request_id" UUID NOT NULL,
    "org_id" UUID NOT NULL,
    "user_id" UUID NOT NULL,
    "order_no" INTEGER NOT NULL,
    "status" VARCHAR(10) NOT NULL DEFAULT 'PENDING',
    "method" VARCHAR(4),
    "typed_name" VARCHAR(100),
    "image_sealed" BYTEA,
    "signed_at" TIMESTAMPTZ,
    "reauth_at" TIMESTAMPTZ,
    "consent_version" VARCHAR(20),
    "ip" VARCHAR(45),
    "user_agent" VARCHAR(300),
    "decline_reason" VARCHAR(500),

    CONSTRAINT "signature_signers_pkey" PRIMARY KEY ("request_id","user_id")
);

