-- Part 2: hand-written.
ALTER TABLE signature_requests
  ADD CONSTRAINT signature_requests_status_check CHECK (status IN ('OPEN', 'COMPLETED', 'DECLINED', 'CANCELLED')),
  ADD CONSTRAINT signature_requests_sha_check CHECK (source_sha256 ~ '^[0-9a-f]{64}$' AND (signed_sha256 IS NULL OR signed_sha256 ~ '^[0-9a-f]{64}$')),
  ADD CONSTRAINT signature_requests_completed_check CHECK ((status = 'COMPLETED') = (signed_version_id IS NOT NULL AND signed_sha256 IS NOT NULL AND completed_at IS NOT NULL));
ALTER TABLE signature_signers
  ADD CONSTRAINT signature_signers_status_check CHECK (status IN ('PENDING', 'SIGNED', 'DECLINED')),
  -- A signature is complete evidence or nothing: method, time, re-authentication, consent, IP.
  ADD CONSTRAINT signature_signers_signed_check CHECK (status <> 'SIGNED' OR (
    method IN ('DRAW', 'TYPE') AND signed_at IS NOT NULL AND reauth_at IS NOT NULL AND consent_version IS NOT NULL AND ip IS NOT NULL
    AND ((method = 'DRAW' AND image_sealed IS NOT NULL) OR (method = 'TYPE' AND typed_name IS NOT NULL)))),
  ADD CONSTRAINT signature_signers_declined_check CHECK (status <> 'DECLINED' OR decline_reason IS NOT NULL);

DO $$
DECLARE
  t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY['signature_requests', 'signature_signers'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY %I ON %I FOR ALL
         USING (org_id = NULLIF(current_setting(''app.org_id'', true), '''')::uuid)
         WITH CHECK (org_id = NULLIF(current_setting(''app.org_id'', true), '''')::uuid)',
      t || '_org_policy', t);
  END LOOP;
END
$$;
-- Signature evidence is never deleted by the app.
GRANT SELECT, INSERT, UPDATE ON signature_requests, signature_signers TO hrvo_app;
REVOKE DELETE, TRUNCATE ON signature_requests, signature_signers FROM hrvo_app;

-- A signed signer row is final.
CREATE FUNCTION fn_signature_signer_final() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.status = 'SIGNED' THEN
    RAISE EXCEPTION 'a signature cannot be changed once given';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER trg_signature_signer_final BEFORE UPDATE ON signature_signers FOR EACH ROW EXECUTE FUNCTION fn_signature_signer_final();

ALTER TABLE document_access_logs DROP CONSTRAINT document_access_logs_action_check;
ALTER TABLE document_access_logs
  ADD CONSTRAINT document_access_logs_action_check CHECK (action IN (
    'VIEW', 'DOWNLOAD', 'UPLOAD', 'SHARE', 'DELETE', 'ACL_CHANGE', 'PASSWORD_FAIL', 'RECOVER', 'RESTORE', 'QUARANTINE', 'UPDATE',
    'SHRED', 'TRASH_RESTORE', 'LEGAL_HOLD', 'PASSWORD_SET', 'PASSWORD_REMOVED', 'REAUTH_REQUIRED', 'SIGN'));
